<section id="page-settings" class="page-section" hidden><div class="split"><form class="card" id="defaults-form"><h2><?= e(tr('新任务默认配置')) ?></h2><label><?= e(tr('CF SaaS服务设置')) ?><select name="profile_id" id="default-profile"></select></label><label><?= e(tr('DNS 账号')) ?><select name="dns_account_id" id="default-account"></select></label><label><?= e(tr('优选目标')) ?><select name="entry_id" id="default-entry"></select></label><label><?= e(tr('回源预设')) ?><select name="origin_id" id="default-origin"></select></label><label><?= e(tr('默认检查路径')) ?><input name="check_path" value="/" placeholder="/health"></label><label><?= e(tr('预期状态码')) ?><input name="check_statuses" placeholder="200,204"></label><label><?= e(tr('响应关键字（可选）')) ?><input name="check_keyword" maxlength="512"></label><p class="hint"><?= e(tr('默认值用于新任务，已有域名保持当前生效配置。')) ?></p><button class="primary"><?= e(tr('保存默认配置')) ?></button></form><form class="card" data-endpoint="/api/admin/password"><h2><?= e(tr('修改管理员密码')) ?></h2><label><?= e(tr('当前密码')) ?><input type="password" name="current_password" required autocomplete="current-password"></label><label><?= e(tr('新密码')) ?><input type="password" name="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><button class="primary"><?= e(tr('保存新密码')) ?></button></form></div></section>
</main><footer><?= e(tr('Cloudflare SaaS自动接入面板 · v')) ?><?= e(\Panel\Core\Version::current()) ?> <a href="https://github.com/Sigusama/cloudflare-saas-panel/tree/v<?= e(rawurlencode(\Panel\Core\Version::current())) ?>"><?= e(tr('源码')) ?> · AGPLv3</a><span><?= e(tr('所有检测以实际执行结果为准')) ?></span></footer></div>
<dialog id="inventory-adopt-dialog" class="wide-dialog"><div class="dialog-head"><h2><?= e(tr('核对并纳入管理')) ?></h2><button class="text-button" data-close="inventory-adopt-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div><p class="hint"><?= e(tr('保存当前解析与回源快照，随后执行只读检查。原有 SaaS 主机名、回源与 TXT 保留外部归属。')) ?></p><fieldset id="inventory-adopt-fields"><div id="inventory-adopt-plans"></div></fieldset><p id="inventory-adopt-result" role="status"></p><div class="dialog-actions"><button type="button" class="secondary" data-close="inventory-adopt-dialog"><?= e(tr('关闭')) ?></button><button type="button" class="secondary" id="inventory-preview"><?= e(tr('检查纳管计划')) ?></button><button type="button" class="primary" id="inventory-commit" disabled><?= e(tr('确认纳入管理')) ?></button></div></dialog>
<dialog id="bulk-dialog" class="wide-dialog"><div class="dialog-head"><h2 id="bulk-title"><?= e(tr('批量操作')) ?></h2><button class="text-button" data-close="bulk-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div>
  <div id="bulk-preferred-options" hidden><div class="form-grid"><label><?= e(tr('优选目标')) ?><select id="bulk-entry"></select></label><label><?= e(tr('原有记录接入使用的 SaaS')) ?><select id="bulk-profile"></select></label></div><details><summary><?= e(tr('回源与同名多地址设置')) ?></summary><p class="hint"><?= e(tr('单条原有记录默认使用当前 IP / CNAME 回源；已有 SaaS 保留原回源。多个同名地址需明确回源。')) ?></p><label><?= e(tr('回源 IP 或 CNAME（选填）')) ?><input id="bulk-source" placeholder="<?= e(tr('不填则保留各记录当前源站')) ?>"></label><label class="checkbox"><input type="checkbox" id="bulk-same-name"><?= e(tr('允许将同名全部 A / AAAA / CNAME 合并切换为优选')) ?></label></details></div>
  <p id="bulk-description" class="hint"></p><label id="bulk-delete-options" hidden><?= e(tr('删除处理方式')) ?><select id="bulk-delete-mode"><option value="delete_records"><?= e(tr('删除当前接入解析，并清理面板创建的 SaaS 资源')) ?></option><option value="restore"><?= e(tr('恢复原 DNS，保留云端主机名')) ?></option><option value="delete_remote"><?= e(tr('恢复原 DNS，并删除面板创建的主机名')) ?></option><option value="forget"><?= e(tr('仅移除面板管理，保留云端资源')) ?></option></select></label>
  <p id="bulk-mode-help" class="hint"></p><div id="bulk-summary" class="bulk-summary" role="status"></div>
  <div class="table-wrap"><table><thead><tr><th><?= e(tr('选中记录')) ?></th><th><?= e(tr('版本')) ?></th><th><?= e(tr('检查 / 提交结果')) ?></th><th><?= e(tr('详情')) ?></th></tr></thead><tbody id="bulk-result-rows"></tbody></table></div>
  <div class="dialog-actions"><button type="button" class="secondary" data-close="bulk-dialog"><?= e(tr('关闭')) ?></button><button type="button" class="secondary" id="raw-back-edit" hidden><?= e(tr('返回编辑')) ?></button><button type="button" class="secondary" id="bulk-preview"><?= e(tr('重新检查')) ?></button><button type="button" class="primary" id="bulk-confirm" disabled><?= e(tr('确认执行')) ?></button></div>
</dialog>
<dialog id="raw-dns-dialog"><div class="dialog-head"><h2 id="raw-dns-title"><?= e(tr('编辑 DNS 记录')) ?></h2><button class="text-button" data-close="raw-dns-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div><form id="raw-dns-form">
<div class="form-grid"><label><?= e(tr('类型')) ?><input name="type" required list="raw-dns-types"><datalist id="raw-dns-types"><option>A</option><option>AAAA</option><option>CNAME</option><option>TXT</option><option>MX</option><option>NS</option><option>CAA</option><option>SRV</option><option>HTTPS</option><option>SVCB</option><option>TLSA</option><option>SSHFP</option><option>URI</option></datalist></label><label><?= e(tr('名称')) ?><input name="name" required placeholder="<?= e(tr('@ 或子域名')) ?>"></label></div>
<label><?= e(tr('内容')) ?><textarea name="content" rows="3" required></textarea></label><div class="form-grid"><label><?= e(tr('TTL（秒，1 为自动）')) ?><input name="ttl" type="number" min="1" max="86400" required></label><label id="raw-priority-label"><?= e(tr('优先级')) ?><input name="priority" type="number" min="0" max="65535"></label></div>
<label id="raw-proxy-label" class="checkbox"><input name="proxied" type="checkbox"><?= e(tr('开启小黄云')) ?></label><label><?= e(tr('注释')) ?><input name="comment" maxlength="500"></label>
<details><summary><?= e(tr('高级记录字段')) ?></summary><label><?= e(tr('类型数据（JSON 对象）')) ?><textarea name="data" rows="5" spellcheck="false"></textarea></label><label><?= e(tr('标签（JSON 数组）')) ?><textarea name="tags" rows="2" spellcheck="false"></textarea></label><label><?= e(tr('记录设置（JSON 对象）')) ?><textarea name="settings" rows="3" spellcheck="false"></textarea></label></details>
<p class="hint"><?= e(tr('下一步核对修改前后的差异，确认提交后执行。')) ?></p><div class="dialog-actions"><button type="button" class="secondary" data-close="raw-dns-dialog"><?= e(tr('取消')) ?></button><button class="primary"><?= e(tr('预览修改')) ?></button></div></form></dialog>
<dialog id="record-dialog"><div class="dialog-head"><div><div class="eyebrow" id="record-zone-label">DNS RECORD</div><h2 id="record-form-title"><?= e(tr('添加 DNS 记录')) ?></h2></div><button class="text-button" data-close="record-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div>
  <form id="record-form"><input type="hidden" name="domain_id"><input type="hidden" name="expected_version">
    <fieldset class="dns-mode-field"><legend><?= e(tr('DNS 模式')) ?></legend><input type="hidden" name="dns_mode" value="preferred"><div class="dns-mode-switch" role="group" aria-label="<?= e(tr('DNS 模式')) ?>"><button type="button" data-dns-mode="dns_only" aria-pressed="false"><?= e(tr('☁ 关云 · 仅 DNS')) ?></button><button type="button" data-dns-mode="proxied" aria-pressed="false"><?= e(tr('☁ 开小黄云')) ?></button><button type="button" data-dns-mode="preferred" aria-pressed="true" class="selected"><?= e(tr('✦ 优选')) ?></button></div></fieldset>
    <label><?= e(tr('名称')) ?><input name="name" required placeholder="<?= e(tr('www 或 @')) ?>"><small id="record-name-hint"></small></label>
    <label><?= e(tr('回源类型')) ?><select name="type" id="record-type"><option value="auto" selected><?= e(tr('IP（默认，IPv4 / IPv6 自动识别）')) ?></option><option value="CNAME"><?= e(tr('CNAME 域名')) ?></option><option value="preset" hidden><?= e(tr('保留已有回源配置')) ?></option></select></label>
    <label id="record-source-label"><?= e(tr('回源 IP')) ?><input name="source_ip" required placeholder="<?= e(tr('填写网站源站的公网 IP')) ?>"></label>
    <label id="record-hostname-label" hidden><?= e(tr('回源 CNAME 域名')) ?><input name="source_hostname" placeholder="origin.example.com" list="record-origin-suggestions"><datalist id="record-origin-suggestions"></datalist></label>
    <label id="record-entry-label"><?= e(tr('优选目标')) ?><select name="entry_id" id="record-entry" required></select><small><?= e(tr('选择已配置的自定义入口，业务记录 CNAME 到该入口。')) ?></small></label>
    <label id="record-preset-label" hidden><?= e(tr('当前回源配置')) ?><select name="origin_id" id="record-origin"></select></label>
    <details id="record-advanced"><summary><?= e(tr('高级设置（通常无需修改）')) ?></summary><label><?= e(tr('CF SaaS服务设置')) ?><select name="profile_id" id="record-profile" required></select></label><div class="form-grid"><label><?= e(tr('检查路径')) ?><input name="check_path" required value="/"></label><label><?= e(tr('预期状态码')) ?><input name="check_statuses" required></label></div><label><?= e(tr('响应关键字（可选）')) ?><input name="check_keyword" maxlength="512"></label></details>
    <p class="hint" id="record-preview"></p><label class="checkbox"><input type="checkbox" name="replace_existing"><?= e(tr('授权替换该记录已有的 A / AAAA / CNAME 解析')) ?></label>
    <div class="dialog-actions"><button class="secondary" type="button" data-close="record-dialog"><?= e(tr('取消')) ?></button><button class="primary"><?= e(tr('保存并自动接入')) ?></button></div>
  </form>
</dialog>
<dialog id="import-dialog"><div class="dialog-head"><h2><?= e(tr('导入配置与记录')) ?></h2><button class="text-button" data-close="import-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div>
  <form id="import-form"><label><?= e(tr('选择面板导出的 JSON 文件')) ?><input id="import-file" type="file" accept=".json,application/json" required></label><p class="hint"><?= e(tr('文件不含凭据。先将文件中的账号绑定到已添加并同步 Zone 的本地账号。导入不会替换已有域名的生效配置。')) ?></p><div id="import-bindings"></div><label class="checkbox"><input id="import-defaults" type="checkbox"><?= e(tr('同时导入新任务默认配置')) ?></label><button class="secondary" id="preview-import"><?= e(tr('检查并预览')) ?></button><pre id="import-preview" hidden></pre><div class="dialog-actions"><button class="secondary" type="button" data-close="import-dialog"><?= e(tr('取消')) ?></button><button class="primary" id="commit-import" type="button" disabled><?= e(tr('确认导入并创建接入任务')) ?></button></div></form>
</dialog>
<dialog id="domain-dialog"><div class="dialog-head"><div><div class="eyebrow">ONBOARDING</div><h2><?= e(tr('添加接入域名')) ?></h2></div><button class="text-button" data-close="domain-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div><form id="domain-form"><label><?= e(tr('域名')) ?><textarea name="hostnames" required rows="4" placeholder="app.example.com&#10;www.example.com"></textarea><small><?= e(tr('一行一个，最多 50 个。每个域名单独执行。')) ?></small></label><div class="form-grid"><label><?= e(tr('CF SaaS服务设置')) ?><select name="profile_id" class="profile-select" id="domain-profile" required></select></label><label><?= e(tr('DNS 账号')) ?><select name="dns_account_id" class="account-select" required></select></label><label><?= e(tr('优选目标')) ?><select name="entry_id" id="domain-entry" required></select></label><label><?= e(tr('回源预设')) ?><select name="origin_id" id="domain-origin" required></select></label></div><label class="checkbox"><input type="checkbox" name="replace_existing"><?= e(tr('授权替换这些域名已有的 A / AAAA / CNAME 记录')) ?></label><p class="hint"><?= e(tr('Cloudflare 接入可能先配置标准 CNAME，再切换所选入口。验证成功后清理本轮新建临时 TXT，无关记录保留。')) ?></p><div class="dialog-actions"><button type="button" class="secondary" data-close="domain-dialog"><?= e(tr('取消')) ?></button><button class="primary"><?= e(tr('提交接入任务')) ?></button></div></form></dialog>
<dialog id="detail-dialog" class="wide-dialog"><div class="dialog-head"><h2 id="detail-title"><?= e(tr('任务详情')) ?></h2><button class="text-button" data-close="detail-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div><div id="detail-content"></div></dialog>
<dialog id="change-dialog"><div class="dialog-head"><div><div class="eyebrow">CONFIGURATION CHANGE</div><h2><?= e(tr('切换入口与回源')) ?></h2></div><button class="text-button" data-close="change-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div><p id="change-current" class="hint"></p><form id="change-form"><input name="domain_id" type="hidden"><input name="expected_version" type="hidden"><label><?= e(tr('优选目标')) ?><select name="entry_id" id="change-entry" required></select></label><label><?= e(tr('回源预设')) ?><select name="origin_id" id="change-origin" required></select></label><p id="change-target" class="hint"></p><div class="form-grid"><label><?= e(tr('检查路径')) ?><input name="check_path" required placeholder="/health"></label><label><?= e(tr('预期状态码')) ?><input name="check_statuses" required placeholder="200,204"></label></div><label><?= e(tr('响应关键字（可选）')) ?><input name="check_keyword" maxlength="512"></label><label class="checkbox"><input type="checkbox" name="replace_existing"><?= e(tr('允许以当前 DNS 为基线接管已偏离面板配置的入口记录')) ?></label><p class="hint"><?= e(tr('保存后由后台切换并检查访问；检查失败会恢复本次入口和回源变更。不会修改同一预设下的其他域名。')) ?></p><div class="dialog-actions"><button type="button" class="secondary" data-close="change-dialog"><?= e(tr('取消')) ?></button><button class="primary"><?= e(tr('提交切换任务')) ?></button></div></form></dialog>
<dialog id="remove-dialog"><div class="dialog-head"><h2><?= e(tr('移除域名管理')) ?></h2><button class="text-button" data-close="remove-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div><form id="remove-form"><input name="domain_id" type="hidden"><label><?= e(tr('处理方式')) ?><select name="mode"><option value="forget"><?= e(tr('仅移除面板管理，保留云端 DNS 与主机名')) ?></option><option value="restore"><?= e(tr('恢复原 DNS，保留云端主机名')) ?></option><option value="delete_remote"><?= e(tr('恢复原 DNS，并删除本面板创建的主机名')) ?></option></select></label><p class="hint"><?= e(tr('历史与日志保留。复用的云端主机名不会自动删除。恢复任务需要先处理该域名未结束的其他任务。')) ?></p><button class="primary"><?= e(tr('执行所选操作')) ?></button></form></dialog>
<dialog id="key-dialog"><div class="dialog-head"><h2><?= e(tr('保存 API Key')) ?></h2><button class="text-button" data-close="key-dialog" aria-label="<?= e(tr('关闭')) ?>">×</button></div><p><?= e(tr('此明文只展示一次，关闭后无法再次读取。')) ?></p><pre id="new-key"></pre><button class="primary" id="copy-key"><?= e(tr('复制 Key')) ?></button></dialog><div class="toast" id="toast" role="status" hidden></div></body></html>
